SourceCode.Declaration:
/// <summary>
/// One counted line in a DIRECT submit. MarkedOnly means the worker marked the line counted
/// without a quantity; what that means for the journal is the server's decision. Timestamps are
/// ISO 8601 UTC strings from the device ("2026-09-30T10:15:00Z").
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountDirectCountRow
{
    real    lineNumber;
    real    countedQuantity;
    boolean markedOnly;
    str     countedBy;
    str     countedAtUtc;
    str     countStartedAtUtc;

}

Method.Source:
[DataMemberAttribute('LineNumber')]
public real parmLineNumber(real _value = lineNumber)
{
    lineNumber = _value;
    return lineNumber;
}

[DataMemberAttribute('CountedQuantity')]
public real parmCountedQuantity(real _value = countedQuantity)
{
    countedQuantity = _value;
    return countedQuantity;
}

[DataMemberAttribute('MarkedOnly')]
public boolean parmMarkedOnly(boolean _value = markedOnly)
{
    markedOnly = _value;
    return markedOnly;
}

[DataMemberAttribute('CountedBy')]
public str parmCountedBy(str _value = countedBy)
{
    countedBy = _value;
    return countedBy;
}

[DataMemberAttribute('CountedAtUtc')]
public str parmCountedAtUtc(str _value = countedAtUtc)
{
    countedAtUtc = _value;
    return countedAtUtc;
}

[DataMemberAttribute('CountStartedAtUtc')]
public str parmCountStartedAtUtc(str _value = countStartedAtUtc)
{
    countStartedAtUtc = _value;
    return countStartedAtUtc;
}
